-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "koKR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.monk.brewmaster.Name"] = "추천"
L["rm.mop.monk.brewmaster.Description"] = "양조 전문화에서 자동으로 선택됩니다. 후려차기로 건들건들을 유지하고, 기가 맞을 때마다 맥주통 휘두르기, 다쳤을 때 해악 축출(35% 미만이면 즉시), 기력 소모용으로 타, 범의 힘과 무료 빈틈 채우기로 범의 장풍(34레벨 전에는 타로 기를 생성), 사용할 수 있을 때 절명의 손길을 사용합니다. 전투 밖 원거리에서는: 기의 물결, 술안개, 충돌 또는 맥주통 휘두르기. 적이 셋 이상이면: 비취 돌풍, 불의 숨결, 그리고 건들건들이 남아 있는 동안에만 회전 학다리차기. 알림: 건우지세, 황제의 유산, 큰 시간차에 정화주(건들건들이 넉넉하면 중간 시간차에도), 6중첩부터 묘주, 막강한 방어와 함께 방어 자세, 원기주, 쉬엔, 생명력이 낮으면 강화주, 해악 감퇴 또는 마법 해소, 손날 찌르기. 흑우 조각상 알림은 꺼져 있으며, 해악 방지, 명상, 조롱은 직접 판단합니다."
L["rm.mop.monk.brewmaster.offensive.Name"] = "공격 우선 (시뮬레이터)"
L["rm.mop.monk.brewmaster.offensive.Description"] = "양조 기본 제공 로테이션의 대안으로, 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. 콘텐츠보다 장비가 좋은 방어 전담을 위한 시뮬레이터의 공격 우선 목록을 따릅니다: 맥주통 휘두르기 전에 비취 돌풍, 기는 피해를 위해 후려차기에 쓰며, 일상적인 정화주나 방어 자세는 없습니다(정화주는 15단계 세트의 정화력 발동 시에만 표시). 묘주, 원기주, 쉬엔, 강화주는 여전히 알림으로 나옵니다."
L["rm.mop.monk.mistweaver.Name"] = "추천"
L["rm.mop.monk.mistweaver.Description"] = "운무 전문화에서 자동으로 선택됩니다. 우호적 대상이 있으면 그 대상을 치유합니다: 재사용 대기시간마다 소생의 안개, 근처 아군 셋 이상이 다쳤으면 고양감, 기를 위해 해악 축출과 기 특성, 다친 그룹에 비취 돌풍 또는 회전 학다리차기, 생명의 안개 5중첩에서 쇄도의 안개, 대상이 80% 미만이면 위안의 안개, 그다음 그 정신 집중 안에서 포용의 안개와 쇄도의 안개. 적 대상이 있으면 주먹 치유를 합니다: 범의 힘과 용의 열의를 유지하기 위해 몸의 기억에 범의 장풍과 후려차기, 기가 가득하면 후려차기, 생명의 안개 5중첩에서 쇄도의 안개, 기를 위해 소생의 안개와 해악 축출, 타. 알림: 현룡지세, 황제의 유산, 그룹에서 옥룡 조각상, 한가한 순간에 마나 차, 집중의 천둥 차, 원기주, 35% 미만인 아군에게 기의 고치, 쉬엔, 해독, 방어 기술, 손날 찌르기. 누구를 치유할지는 직접 고르며, 재활(알림 꺼짐)과 치유의 구슬은 직접 판단합니다."
L["rm.mop.monk.unspecialized.Name"] = "전문화 선택 전"
L["rm.mop.monk.unspecialized.Description"] = "1–9레벨이나 아직 전문화를 고르지 않은 수도사용이며, 전문화를 고르는 즉시 전문화 기본 제공 로테이션이 넘겨받습니다. 맹호지세와 범의 힘을 유지하고, 기 두 개를 후려차기에 쓰며, 다쳤을 때는 해악 축출, 그 외에는 타를 사용합니다."
L["rm.mop.monk.windwalker.Name"] = "추천"
L["rm.mop.monk.windwalker.Description"] = "풍운 전문화에서 자동으로 선택됩니다. 사용할 수 있을 때 절명의 손길, 범의 힘을 유지하기 위한 범의 장풍, 재사용 대기시간마다 해오름차기, 기의 물결, 강제 연계 발동, 가만히 서 있고 정신 집중 중에 기력이 가득 차지 않을 때 분노의 주먹, 기가 둘 부족하면 타(다쳤으면 대신 해악 축출), 다음 해오름차기에 쓸 기를 남기면서 후려차기. 적이 둘 이상이면 해오름차기로 약화 효과를 유지하고, 셋부터 회전 학다리차기나 비취 돌풍이 추가됩니다. 알림: 맹호지세, 황제의 유산과 백호의 유산, 19중첩에서 호안주(소모할 기가 있으면 15, 피의 욕망 중이거나 전투 막바지에는 10), 기력이 낮으면 기력 회복주, 원기주, 쉬엔, 적이 둘이면 폭풍과 대지와 불(두 번째 적에게 시전), 업보의 손아귀, 방어 기술, 손날 찌르기. 기력 최대치 확인은 기력 기준값이므로 내 가속에 맞게 조정하세요."
L["rm.mop.monk.windwalker.simc.Name"] = "SimulationCraft 5.4.8 (Hekili와 MaxDps)"
L["rm.mop.monk.windwalker.simc.Description"] = "풍운 기본 제공 로테이션의 대안으로, 기본적으로 꺼져 있습니다: 이것을 켜고 그것을 끄거나, 이것의 우선순위를 높이세요. Hekili와 MaxDps 애드온에 들어 있는 원래 SimulationCraft 목록입니다: 범의 힘은 3초 남았을 때 갱신, 약화 효과가 없는 동안 해오름차기 먼저, 분노의 주먹은 호안주(활성 또는 15중첩)를 위해 보류, 호안주는 20중첩이거나 기와 두 강화 효과가 있을 때 15중첩에서 사용합니다. 적이 셋 이상이면 회전 학다리차기에 소모하고, 해오름차기는 기가 가득할 때만 사용하며, 기력 60 미만에서는 기력을 모읍니다."
L["rm.retail.monk.brewmaster.Name"] = "Blizzard 전투 보조, 양조주 포함"
L["rm.retail.monk.brewmaster.Description"] = "양조 전문화에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며, 시전이나 정신 집중 중에는 기다립니다. 전투 보조는 양조주를 쓰지 않으므로, Icy Veins의 조언대로 양조주는 그 옆에 알림으로 표시됩니다: 흑우주, 흑우 니우짜오의 원령, 정화주, 천신주 또는 천신의 주입, 절명의 손길은 전투 중 준비될 때마다 강조됩니다(Rotation Master는 아직 시간차를 읽을 수 없으므로 시간차가 얼마나 큰지는 직접 판단합니다). 또한 차단 가능한 시전에 손날 찌르기, 전투 중 준비될 때마다 강화주와 종족 재사용 대기시간 기술도 알려 줍니다. 적의 시전은 전투 중 숨겨지므로 차단은 게임이 시전을 보여 주는 곳에서만 강조되며, Retail에서는 생명력이 숨겨지므로 강화주를 언제 쓸지는 직접 판단합니다."
L["rm.retail.monk.brewmaster.guide.Name"] = "참고용 (Icy Veins)"
L["rm.retail.monk.brewmaster.guide.Description"] = "참고용이며 기본적으로 꺼져 있습니다. Icy Veins의 양조 우선순위입니다(SimulationCraft도 큰 틀에서 같음). 한밤 전투에서는 의식 상실 연계, 술통을 비워라, 충전이 숨겨지므로 그곳에서는 실행할 수 없습니다. 맥주통 휘두르기로 끌어옵니다. 후려차기; 기의 파동(조화의 종사); 의식 상실 연계 발동 시 범의 장풍; 충전이 가득 찼거나 술통을 비워라가 있으면 맥주통 휘두르기; 불의 숨결; 폭발하는 맥주통 전에 비취 돌풍; 기의 파동(음영파); 맥주통 휘두르기; 적이 셋 이상이면 비취 돌풍과 회전 학다리차기; 범의 장풍; 해악 축출. 알림: 정화주와 천신주를 다 쓴 뒤 흑우주, 흑우 니우짜오의 원령, 정화주, 천신주 또는 천신의 주입, 절명의 손길, 그리고 유틸리티 알림."
L["rm.retail.monk.initial.Name"] = "Blizzard 전투 보조"
L["rm.retail.monk.initial.Description"] = "전문화를 선택하기 전(게임이 수도사의 초기 전문화를 보고하는 동안)에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며, 시전이나 정신 집중 중에는 기다립니다. 이와 함께 모든 수도사 기본 제공 로테이션이 공유하는 알림을, 해당 주문을 배운 뒤에 각각 제공합니다. 10레벨에 전문화를 선택하면 해당 전문화의 기본 제공 로테이션이 대신합니다."
L["rm.retail.monk.mistweaver.Name"] = "참고용 (Icy Veins)"
L["rm.retail.monk.mistweaver.Description"] = "참고용이며 기본적으로 꺼져 있습니다. Blizzard는 치유 전담용 전투 보조 목록을 제공하지 않고, 한밤 전투에서는 아군의 생명력, 소생의 안개 충전, 마나 차 중첩, 발동 효과가 애드온에 숨겨지므로 치유 조언은 불가능합니다. 치유 주문은 직접 고르세요. 적대적 대상에게는 주먹 치유(피스트위빙)의 빈틈 채우기인 해오름차기, 후려차기, 범의 장풍을 제안하고, 우호적 대상이거나 대상이 없으면 아무것도 제안하지 않습니다. 알림: 손날 찌르기, 전투 중 준비될 때마다 강화주와 종족 재사용 대기시간 기술."
L["rm.retail.monk.windwalker.Name"] = "Blizzard 전투 보조"
L["rm.retail.monk.windwalker.Description"] = "풍운 전문화에 권장됩니다. Blizzard의 전투 보조가 다음으로 제안하는 주문을 강조합니다. 한밤 전투에서 게임이 애드온에 아직 읽기를 허용하는 유일한 로테이션 조언이며(연계 일격도 이미 지킵니다), 시전이나 정신 집중 중에는 기다립니다. 이와 함께 전투 보조가 플레이어에게 맡기는 것을 알려 줍니다: 전투 중 등선, 천신합일, 백호 쉬엔의 원령, 업보의 손아귀, 차단 가능한 시전에 손날 찌르기, 전투 중 준비될 때마다 강화주와 종족 재사용 대기시간 기술. 적의 시전은 전투 중 숨겨지므로 차단은 게임이 시전을 보여 주는 곳에서만 강조되며, Retail에서는 생명력이 숨겨지므로 강화주를 언제 쓸지는 직접 판단합니다."
L["rm.retail.monk.windwalker.guide.Name"] = "참고용 (Icy Veins와 SimulationCraft)"
L["rm.retail.monk.windwalker.guide.Description"] = "참고용이며 기본적으로 꺼져 있습니다. Icy Veins의 천신의 대변자 우선순위입니다. 모든 단계는 연계 일격을 지키며(직전에 시전한 주문은 반복하지 않음), 기와 자신의 시전은 계속 읽을 수 있지만 옥룡의 마음, 등선, 후려차기!, 츠지의 춤은 한밤 전투에서 숨겨지므로 그곳에서는 실행할 수 없으며, Retail에서는 기력이 숨겨지므로 기력이 최대치에 도달하기 전의 범의 장풍은 빠져 있습니다. 쉬엔까지 10초 넘게 남았으면 소용돌이 용의 주먹; 기가 부족하거나 등선이 끝날 때 정점의 발구르기; 옥룡의 마음이 없으면 천신합일; 옥룡의 마음이 끝날 때 분노의 주먹; 천신합일, 백호 쉬엔의 원령, 분노의 주먹, 소용돌이 용의 주먹, 바람의 군주의 일격; 분노의 주먹에 쓸 기가 부족하면 후려차기; 질풍차기, 해오름차기; 후려차기! 충전 2회이거나 등선 중이면 후려차기; 등선 중이거나 츠지의 춤 발동 시 회전 학다리차기; 절명의 손길; 빈틈 채우기로 범의 장풍, 후려차기, 날카로운 바람. 알림: 업보의 손아귀, 그리고 유틸리티 알림."
